var TTS_PREGENERATED = {
  "prompt_rewrite_done": "data:audio/mpeg;base64,",
  "prompt_rewrite_start": "data:audio/mpeg;base64,",
  "prompt_rewrite_success": "data:audio/mpeg;base64,",
  "voice_1": "data:audio/mpeg;base64,",
  "voice_10": "data:audio/mpeg;base64,",
  "voice_2": "data:audio/mpeg;base64,",
  "voice_3": "data:audio/mpeg;base64,",
  "voice_4": "data:audio/mpeg;base64,",
  "voice_5": "data:audio/mpeg;base64,",
  "voice_6": "data:audio/mpeg;base64,",
  "voice_7": "data:audio/mpeg;base64,",
  "voice_8": "data:audio/mpeg;base64,",
  "voice_9": "data:audio/mpeg;base64,",
};

function _getPregeneratedTts(voiceId){if(typeof TTS_PREGENERATED==='undefined')return null;var k='voice_'+voiceId;return TTS_PREGENERATED[k]||null;}
function _getPregeneratedPrompt(promptKey){if(typeof TTS_PREGENERATED==='undefined')return null;var k='prompt_'+promptKey;return TTS_PREGENERATED[k]||null;}
var _ttsSharedAudio=null;
var _ttsBlobUrlMap={};
function _base64ToBlobUrl(dataUri){if(!dataUri||dataUri.indexOf('data:')!==0)return dataUri;try{var parts=dataUri.split(',');var mimeMatch=parts[0].match(/data:([^;]+)/);var mime=mimeMatch?mimeMatch[1]:'audio/mpeg';var b64=parts[1]||'';var byteStr=atob(b64);var len=byteStr.length;var arr=new Uint8Array(len);for(var i=0;i<len;i++)arr[i]=byteStr.charCodeAt(i);var blob=new Blob([arr],{type:mime});return URL.createObjectURL(blob);}catch(e){console.log('[TTS-BLOB] Conversion failed:',e);return dataUri;}}
function _getTtsBlobUrl(key,dataUri){if(_ttsBlobUrlMap[key])return _ttsBlobUrlMap[key];var url=_base64ToBlobUrl(dataUri);_ttsBlobUrlMap[key]=url;return url;}
function _playPregeneratedTts(voiceId,volume,playbackRate){var d=_getPregeneratedTts(voiceId);if(!d)return null;try{var url=_getTtsBlobUrl('voice_'+voiceId,d);if(!_ttsSharedAudio){_ttsSharedAudio=new Audio();}_ttsSharedAudio.pause();_ttsSharedAudio.onended=null;_ttsSharedAudio.onerror=null;_ttsSharedAudio.src=url;_ttsSharedAudio.volume=volume||1.0;_ttsSharedAudio.playbackRate=playbackRate||1.0;_ttsSharedAudio.play().catch(function(e){console.log('[TTS-PREGEN] Play failed:',e)});return _ttsSharedAudio;}catch(e){return null;}}
function _playPregeneratedPrompt(promptKey){var d=_getPregeneratedPrompt(promptKey);if(!d)return null;try{var url=_getTtsBlobUrl('prompt_'+promptKey,d);if(!_ttsSharedAudio){_ttsSharedAudio=new Audio();}_ttsSharedAudio.pause();_ttsSharedAudio.onended=null;_ttsSharedAudio.onerror=null;_ttsSharedAudio.src=url;_ttsSharedAudio.volume=0.8;_ttsSharedAudio.play().catch(function(e){console.log('[TTS-PREGEN] Prompt failed:',e)});return _ttsSharedAudio;}catch(e){return null;}}
